-- Generat per data/scripts/build-seed-astronomia.ts. No l'editis a mà.
-- Codis estables: una segona càrrega actualitza i no duplica files.

begin;

on conflict (codi) do update set
  organitzacio = excluded.organitzacio,
  titol = excluded.titol,
  url = excluded.url,
  any_publicacio = excluded.any_publicacio,
  consultat_el = excluded.consultat_el
where (fonts_astronomiques.organitzacio, fonts_astronomiques.titol, fonts_astronomiques.url, fonts_astronomiques.any_publicacio, fonts_astronomiques.consultat_el) is distinct from (excluded.organitzacio, excluded.titol, excluded.url, excluded.any_publicacio, excluded.consultat_el);

on conflict (codi) do update set
  tipus_codi = excluded.tipus_codi,
  periodicitat = excluded.periodicitat,
  publicable_calendari = excluded.publicable_calendari,
  velocitat_km_s = excluded.velocitat_km_s,
  textos = excluded.textos
where (fenomens_astronomics.tipus_codi, fenomens_astronomics.periodicitat, fenomens_astronomics.publicable_calendari, fenomens_astronomics.velocitat_km_s, fenomens_astronomics.textos) is distinct from (excluded.tipus_codi, excluded.periodicitat, excluded.publicable_calendari, excluded.velocitat_km_s, excluded.textos);

on conflict (codi) do update set
  fenomen_codi = excluded.fenomen_codi,
  font_codi = excluded.font_codi,
  referencia_font = excluded.referencia_font,
  inici = excluded.inici,
  fi = excluded.fi,
  maxim = excluded.maxim,
  precisio = excluded.precisio,
  rellevant_catalunya = excluded.rellevant_catalunya,
  rellevancia = excluded.rellevancia,
  dificultat_observacio = excluded.dificultat_observacio,
  zhr = excluded.zhr,
  radiant_maxim = excluded.radiant_maxim,
  textos = excluded.textos
where (esdeveniments_astronomics.fenomen_codi, esdeveniments_astronomics.font_codi, esdeveniments_astronomics.referencia_font, esdeveniments_astronomics.inici, esdeveniments_astronomics.fi, esdeveniments_astronomics.maxim, esdeveniments_astronomics.precisio, esdeveniments_astronomics.rellevant_catalunya, esdeveniments_astronomics.rellevancia, esdeveniments_astronomics.dificultat_observacio, esdeveniments_astronomics.zhr, esdeveniments_astronomics.radiant_maxim, esdeveniments_astronomics.textos) is distinct from (excluded.fenomen_codi, excluded.font_codi, excluded.referencia_font, excluded.inici, excluded.fi, excluded.maxim, excluded.precisio, excluded.rellevant_catalunya, excluded.rellevancia, excluded.dificultat_observacio, excluded.zhr, excluded.radiant_maxim, excluded.textos);

commit;
